{
  "design": {
    "theme": "chalk",
    "picture_style": "illustration"
  },
  "flow": [
    {"slide": 1, "does": "Recall French introductions and ages", "look_at": {"kind": "none", "shows": null}, "teaches": []},
    {"slide": 2, "does": "Share the approved objectives", "look_at": {"kind": "none", "shows": null}, "teaches": []},
    {"slide": 3, "does": "Teach family nouns and possessive choices", "look_at": {"kind": "diagram", "shows": "Family vocabulary grouped by grammatical gender and number"}, "teaches": [1]},
    {"slide": 4, "does": "Check vocabulary and possessives", "look_at": {"kind": "none", "shows": null}, "teaches": [1]},
    {"slide": 5, "does": "Correct the owner-gender misconception", "look_at": {"kind": "none", "shows": null}, "teaches": [1]},
    {"slide": 6, "does": "Model name, age and personality sentences", "look_at": {"kind": "picture", "shows": "A cheerful teenage sister"}, "teaches": [2]},
    {"slide": 7, "does": "Try a closely matched description", "look_at": {"kind": "none", "shows": null}, "teaches": [2]},
    {"slide": 8, "does": "Check adjective agreement", "look_at": {"kind": "none", "shows": null}, "teaches": [2]},
    {"slide": 9, "does": "Teach siblings and negative statements", "look_at": {"kind": "none", "shows": null}, "teaches": [3]},
    {"slide": 10, "does": "Model a connected family description", "look_at": {"kind": "none", "shows": null}, "teaches": [1, 2, 3]},
    {"slide": 11, "does": "Write a closely matched family description", "look_at": {"kind": "none", "shows": null}, "teaches": [1, 2, 3]},
    {"slide": 12, "does": "Apply the language to a new family profile", "look_at": {"kind": "none", "shows": null}, "teaches": [1, 2, 3]}
  ],
  "title": {
    "template": "title",
    "heading": "Ma famille",
    "lead": "My family\nRappelle-toi : dis « My name is… » et « I am 12 years old » en français.",
    "picture": null
  },
  "slides": [
    {
      "template": "big-visual",
      "heading": "Les membres de ma famille",
      "lead": "Lis les mots. Mon / ma / mes = my.",
      "figure": {
        "kind": "table",
        "shows": "Six family terms grouped by masculine singular, feminine singular and plural",
        "alt": "Mon is used with père and frère; ma with mère and sœur; mes with parents and grands-parents.",
        "title": null,
        "header": ["Masculin : mon", "Féminin : ma", "Pluriel : mes"],
        "rows": [
          ["mon père — my father", "ma mère — my mother", "mes parents — my parents"],
          ["mon frère — my brother", "ma sœur — my sister", "mes grands-parents"],
          ["", "", "my grandparents"]
        ]
      }
    },
    {
      "template": "question-set",
      "heading": "À toi !",
      "questions": [
        "Traduis : my father, my mother, my grandparents.",
        "Complète avec mon, ma ou mes : ___ frère ; ___ sœur ; ___ parents.",
        "Explique en anglais : pourquoi dit-on « mes parents » ?"
      ],
      "instruction": "Écris tes réponses. Write your answers.",
      "picture": null
    },
    {
      "template": "explain",
      "heading": "Mon ou ma : qui décide ?",
      "lead": "Mon / ma matches the French noun, not the person speaking.",
      "points": [
        "Léa dit : « mon père » et « ma mère ».",
        "Paul dit : « mon père » et « ma mère ».",
        "Explique : pourquoi utilisent-ils les mêmes mots ?"
      ]
    },
    {
      "template": "visual-text",
      "heading": "Décrire ma sœur",
      "lead": "Ma sœur s’appelle Léa. Elle a treize ans. Elle est gentille.",
      "points": [
        {"label": "Il / elle", "text": "He / she: s’appelle = is called; a… ans = is… years old."},
        {"label": "Personnalité", "text": "Kind: gentil / gentille. Funny: amusant / amusante."}
      ],
      "figure": {
        "shows": "A cheerful teenage girl, representing the imaginary sister Léa",
        "must_see": ["teenage girl", "friendly smile"],
        "subject": "generic"
      }
    },
    {
      "template": "practice",
      "heading": "Décris un frère",
      "questions": [
        "My brother is called Hugo. Écris la phrase en français.",
        "He is fourteen years old. Écris la phrase en français.",
        "He is kind. Écris la phrase en français."
      ],
      "instruction": "Écris trois phrases. fourteen = quatorze.",
      "picture": null
    },
    {
      "template": "hinge",
      "heading": "Choisis la bonne phrase",
      "stem": "Comment dit-on « My sister is funny » ?",
      "options": [
        "Ma sœur est amusant.",
        "Ma sœur est amusante.",
        "Mon sœur est amusante.",
        "Ma sœur a amusante."
      ],
      "correct": 2
    },
    {
      "template": "explain",
      "heading": "J’ai… / Je n’ai pas de…",
      "lead": "J’ai = I have. Je n’ai pas de = I don’t have any.",
      "points": [
        "J’ai un frère et une sœur. — I have a brother and a sister.",
        "Je n’ai pas de frère. — I don’t have any brothers.",
        "Après « je n’ai pas », un / une devient de."
      ]
    },
    {
      "template": "explain",
      "heading": "Un exemple : ma famille",
      "lead": "J’ai une sœur. Je n’ai pas de frère. Ma sœur s’appelle Léa. Elle a treize ans. Elle est amusante.",
      "points": [
        {"label": "Structure", "text": "Siblings → name → age → personality."},
        {"label": "Vérifie", "text": "Ma sœur → elle → amusante."}
      ]
    },
    {
      "template": "practice",
      "heading": "À toi : écris un paragraphe",
      "questions": [
        "You have one brother and no sisters. Écris deux phrases.",
        "Your brother is called Hugo and is fourteen. Ajoute son nom et son âge.",
        "He is funny. Ajoute sa personnalité."
      ],
      "instruction": "Écris cinq phrases liées. fourteen = quatorze.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Une nouvelle famille",
      "questions": [
        "Camille has two sisters and no brothers. Écris à la place de Camille.",
        "Camille’s father is Marc, aged forty, and kind. Décris-le.",
        "Défi : ajoute que Camille’s mother, Julie, is funny."
      ],
      "instruction": "Écris un paragraphe. two = deux ; forty = quarante.",
      "picture": null
    }
  ]
}
